import java.util.Scanner;

public class Main {
    public static long modExp(long base, long exp, long mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        final long pcon = 1000000007;
        long[] invArr = new long[1000003];
        invArr[1] = 1;
        for (long i = 2; i < 1000003; ++i) {
            long a = pcon / i;
            long b = pcon % i;
            long c = (a * (pcon - invArr[(int)b])) % pcon;
            invArr[(int)i] = c;
        }
        long total = 0;
        if (k == 0) {
            total = 1;
            for (long i = 0; i < p - 1; ++i) {
                total = (total * p) % pcon;
            }
        } else {
            long product = 1;
            long firstFlag = 0;
            long indexVal = 0;
            for (long i = 1; i < p; ++i) {
                product = (product * k) % p;
                if ((product % p) == 1 && firstFlag == 0) {
                    indexVal = i;
                    firstFlag = 1;
                }
            }
            total = 1;
            long t = (p - 1) / indexVal;
            if (k == 1) {
                total = 1;
                for (long i = 0; i < p; ++i) {
                    total = (total * p) % pcon;
                }
            } else {
                long sumVal = 0;
                for (long i = 1; i <= t; ++i) {
                    long temp = (invArr[(int)i] * (t - i + 1)) % pcon;
                    temp = (temp * t) % pcon;
                    temp = (temp * indexVal) % pcon;
                    sumVal = (sumVal + temp) % pcon;
                }
                total = (total + sumVal) % pcon;
            }
        }
        System.out.println(total);
        sc.close();
    }
}
